CREATE DATABASE IF NOT EXISTS bup_lost_found; USE bup_lost_found;
DROP TABLE IF EXISTS notifications; DROP TABLE IF EXISTS claims; DROP TABLE IF EXISTS items; DROP TABLE IF EXISTS categories; DROP TABLE IF EXISTS users;
CREATE TABLE users(user_id INT AUTO_INCREMENT PRIMARY KEY,name VARCHAR(120) NOT NULL,email VARCHAR(150) UNIQUE NOT NULL,password VARCHAR(255) NOT NULL,role ENUM('student','faculty','officer','staff','admin') DEFAULT 'student',phone VARCHAR(30),department VARCHAR(120),created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE categories(category_id INT AUTO_INCREMENT PRIMARY KEY,category_name VARCHAR(80) UNIQUE NOT NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE items(item_id INT AUTO_INCREMENT PRIMARY KEY,item_type ENUM('lost','found') NOT NULL,user_id INT NOT NULL,category_id INT NOT NULL,item_name VARCHAR(150) NOT NULL,description TEXT NOT NULL,item_date DATE NOT NULL,location VARCHAR(180) NOT NULL,image_path VARCHAR(255),status ENUM('Lost','Found','Claimed','Returned','Closed') NOT NULL,verification_status ENUM('Pending','Approved','Rejected') DEFAULT 'Pending',created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(user_id) REFERENCES users(user_id) ON DELETE CASCADE,FOREIGN KEY(category_id) REFERENCES categories(category_id));
CREATE TABLE claims(claim_id INT AUTO_INCREMENT PRIMARY KEY,item_id INT NOT NULL,claimant_id INT NOT NULL,verification_info TEXT NOT NULL,status ENUM('Pending','Approved','Rejected') DEFAULT 'Pending',reviewed_by INT NULL,reviewed_at DATETIME NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(item_id) REFERENCES items(item_id) ON DELETE CASCADE,FOREIGN KEY(claimant_id) REFERENCES users(user_id) ON DELETE CASCADE,FOREIGN KEY(reviewed_by) REFERENCES users(user_id) ON DELETE SET NULL);
CREATE TABLE notifications(notification_id INT AUTO_INCREMENT PRIMARY KEY,user_id INT NOT NULL,message VARCHAR(500) NOT NULL,is_read BOOLEAN DEFAULT FALSE,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(user_id) REFERENCES users(user_id) ON DELETE CASCADE);
CREATE INDEX idx_items_search ON items(item_name,location,item_date); CREATE INDEX idx_items_status ON items(status); CREATE INDEX idx_claim_status ON claims(status);
